fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    assert!(!a.is_empty() && !b.is_empty(), "inputs must be non-empty");
    let m = a.len();
    let n = b.len();
    assert!(
        m == n || m == 1 || n == 1,
        "inputs are not broadcast-compatible"
    );

    let len = m.max(n);

    let out_a = if m == len {
        a
    } else {
        vec![a[0]; len]
    };

    let out_b = if n == len {
        b
    } else {
        vec![b[0]; len]
    };

    (out_a, out_b)
}